//! win32k-rust: Rust translation of ReactOS win32k.sys (GDI + USER).
//!
//! Auto-generated by rustconv (per-file). Do not edit translated modules
//! by hand — re-translate via the pipeline. This umbrella `lib.rs` is the
//! one hand-maintained file: each landed `src/{name}.rs` gets a
//! `pub mod {name};` line here (flat layout, like hal-rust/src/x86).
//!
//! Links into `win32k.sys` via a staticlib umbrella + cohabitation
//! (the translated C file is commented out in `win32ss/CMakeLists.txt`
//! and the Rust `#[no_mangle]` symbol takes over, exactly like the
//! ntoskrnl-rust / hal-rust cohabitation pattern).
//!
//! FFI surfaces:
//!   * `win32k_sys::win32k::*` — the win32k-internal API/layouts
//!     (`_WND`, `_DESKTOP`, `Int*`/`Gre*`/`co_*`/`User*`).
//!   * `ntkrnl_sys::ddk::*`   — the ntoskrnl APIs win32k also calls
//!     (`Ex/Ke/Mm/Ob/Ps/Rtl/Zw/Nt*`).

#![no_std]
#![allow(non_snake_case)]
#![allow(non_camel_case_types)]
#![allow(non_upper_case_globals)]
#![allow(dead_code)]
#![allow(unused_variables)]
#![allow(unused_assignments)]
#![allow(unused_mut)]

extern crate ntkrnl_sys;
extern crate ntprintf;
extern crate ntprintf_w;
extern crate win32k_sys;

// ── Translated modules (one `pub mod` per landed src/<name>.rs) ──────
// Emit a fn twice: `extern "fastcall"` on i386, `extern "C"` elsewhere.
// FASTCALL only exists as a distinct ABI on x86; rustc treats "fastcall" as "C"
// on other arches today and makes it a HARD ERROR on newer toolchains
// (unsupported_calling_conventions). Same pattern as ex-rust's fastcall_export!.
macro_rules! fastcall_fn {
    ($(#[$attr:meta])* $vis:vis unsafe fn $name:ident($($params:tt)*) $(-> $ret:ty)? $body:block) => {
        $(#[$attr])*
        #[cfg(target_arch = "x86")]
        $vis unsafe extern "fastcall" fn $name($($params)*) $(-> $ret)? $body

        $(#[$attr])*
        #[cfg(not(target_arch = "x86"))]
        $vis unsafe extern "C" fn $name($($params)*) $(-> $ret)? $body
    };
}

// win32k's ERR/FIXME/WARN/TRACE (win32kdebug.h) + debug.h's DPRINT/DPRINT1 for the
// whole crate; `#[macro_use]` must precede the modules that call them
// (macro_rules! is textually scoped).
// `NT_ASSERT(x)` and userfuncs.h's `ASSERT_REFS_CO(obj)` are DBG assertions: debug
// assertions here, as ntoskrnl's `ASSERT!` is. Defined once, ahead of every module, so
// none lowers them to an empty fn -- which evaluates the operands the C macro discards.
macro_rules! NT_ASSERT { ($($t:tt)*) => { ntkrnl_sys::nt_assert!($($t)*) }; }
macro_rules! ASSERT_REFS_CO {
    ($obj:expr $(,)?) => {
        debug_assert!(
            unsafe { (*($obj as win32k_sys::win32k::PHEAD)).cLockObj } >= 1,
            "ASSERT_REFS_CO: obj {:p}",
            $obj
        )
    };
}

